import React, { useState, useEffect, useContext } from 'react';
import { useParams, Link } from 'react-router-dom';
import { 
  Building2, 
  MapPin, 
  Briefcase, 
  Target, 
  DollarSign, 
  Calendar, 
  Clock, 
  Users, 
  ArrowLeft, 
  CheckCircle2, 
  X, 
  Sparkles, 
  ShieldCheck, 
  Star,
  ChevronRight,
  ExternalLink,
  MessageSquare,
  FileText,
  AlertTriangle,
  GraduationCap
} from 'lucide-react';
import { AppContext } from '../../App';
import { JobService } from '../../domain/jobService';
import { ApplicationService } from '../../domain/applicationService';

const JobDetails = () => {
  const { id } = useParams();
  const { user, userType } = useContext(AppContext);
  const [jobDetails, setJobDetails] = useState(null);
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showApplicationModal, setShowApplicationModal] = useState(false);
  const [applicationData, setApplicationData] = useState({
    coverLetter: ''
  });
  const [applicationLoading, setApplicationLoading] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    loadJobDetails();
  }, [id]);

  const loadJobDetails = async () => {
    try {
      setLoading(true);
      const details = await JobService.getJobDetails(id);
      setJobDetails(details);

      if (userType === 'employer' || userType === 'admin') {
        const jobApplications = await ApplicationService.getApplicationsByJob(id);
        setApplications(jobApplications);
      }
    } catch (error) {
      console.error('Failed to load job details:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleApplyClick = () => {
    setApplicationData({ coverLetter: '' });
    setMessage('');
    setShowApplicationModal(true);
  };

  const handleApplicationSubmit = async (e) => {
    e.preventDefault();
    setApplicationLoading(true);
    setMessage('');

    try {
      await ApplicationService.submitApplication({
        studentId: user.id,
        jobId: parseInt(id),
        coverLetter: applicationData.coverLetter
      });

      setMessage('Submission successful. Your professional legacy begins.');
      setTimeout(() => {
        setShowApplicationModal(false);
        loadJobDetails();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setApplicationLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'active': { bg: 'bg-emerald-500/10', text: 'text-emerald-400', border: 'border-emerald-500/20' },
      'inactive': { bg: 'bg-pearl-800/10', text: 'text-pearl-600', border: 'border-pearl-800/20' },
      'expired': { bg: 'bg-rose-500/10', text: 'text-rose-400', border: 'border-rose-500/20' },
      'under_review': { bg: 'bg-gold-500/10', text: 'text-gold-500', border: 'border-gold-500/20' },
      'shortlisted': { bg: 'bg-blue-500/10', text: 'text-blue-400', border: 'border-blue-500/20' },
      'accepted': { bg: 'bg-emerald-500/10', text: 'text-emerald-400', border: 'border-emerald-500/20' },
      'rejected': { bg: 'bg-rose-500/10', text: 'text-rose-400', border: 'border-rose-500/20' }
    };

    const config = statusConfig[status] || { bg: 'bg-pearl-800/10', text: 'text-pearl-600', border: 'border-pearl-800/20' };
    return (
      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black border tracking-[0.2em] uppercase ${config.bg} ${config.text} ${config.border}`}>
        {status.replace('_', ' ')}
      </span>
    );
  };

  const isDeadlinePassed = (deadline) => {
    return new Date() > new Date(deadline);
  };

  const canApply = () => {
    if (userType !== 'student') return false;
    if (isDeadlinePassed(jobDetails.job.applicationDeadline)) return false;
    if (user.appliedJobs && user.appliedJobs.includes(parseInt(id))) return false;
    return true;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-gold-500/20 border-t-gold-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!jobDetails) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center p-8">
        <div className="glass p-12 rounded-[3rem] border border-rose-500/20 text-center max-w-md">
           <AlertTriangle size={48} className="text-rose-500 mx-auto mb-6" />
           <h3 className="text-2xl font-serif font-bold text-white mb-2">Record Not Found</h3>
           <p className="text-pearl-600 italic">The strategic mandate you are looking for has been archived or does not exist.</p>
           <Link to="/jobs" className="inline-block mt-8 text-gold-500 font-bold uppercase tracking-widest text-xs border-b border-gold-500/30 pb-1">Return to Registry</Link>
        </div>
      </div>
    );
  }

  const { job } = jobDetails;

  return (
    <div className="min-h-screen bg-onyx-900 pb-24 font-sans text-pearl-200">
      {/* Cinematic Banner */}
      <div className="h-96 bg-onyx-950 relative overflow-hidden">
        <div className="absolute inset-0 bg-gold-gradient opacity-[0.05]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1400px] h-[1400px] bg-gold-500/5 rounded-full blur-[200px]"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full flex flex-col justify-end pb-16 relative z-10">
          <Link to="/jobs" className="flex items-center gap-2 text-pearl-600 hover:text-gold-500 transition-all mb-8 group w-fit">
             <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
             <span className="text-[10px] font-black uppercase tracking-[0.2em]">Return to Opportunities</span>
          </Link>

          <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-10">
            <div className="flex-1">
              <div className="flex items-center gap-4 mb-6">
                 <div className="w-20 h-20 rounded-[2rem] bg-white/5 border border-pearl-900/10 flex items-center justify-center p-4 shadow-2xl backdrop-blur-xl">
                    <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${job.company}`} alt="logo" className="w-full h-full object-contain grayscale brightness-125" />
                 </div>
                 <div>
                    <Link to={`/employer/${job.companyId}`} className="text-gold-500 font-black uppercase tracking-[0.3em] text-[10px] mb-2 block hover:text-gold-400 transition-colors">
                       {job.company} • Corporate Partner
                    </Link>
                    <h1 className="text-4xl md:text-6xl font-serif font-bold text-white tracking-tight leading-none">{job.title}</h1>
                 </div>
              </div>

              <div className="flex flex-wrap gap-8 text-pearl-500 text-sm font-light">
                 <div className="flex items-center gap-3">
                    <MapPin size={18} className="text-gold-500/30" />
                    <span>{job.location}</span>
                 </div>
                 <div className="flex items-center gap-3">
                    <Briefcase size={18} className="text-gold-500/30" />
                    <span>{job.jobType}</span>
                 </div>
                 <div className="flex items-center gap-3">
                    <Target size={18} className="text-gold-500/30" />
                    <span>{job.experience} Expertise</span>
                 </div>
                 <div className="flex items-center gap-3">
                    <DollarSign size={18} className="text-gold-500/30" />
                    <span className="font-bold text-pearl-200 tracking-tighter uppercase">{job.salary}</span>
                 </div>
              </div>
            </div>

            <div className="flex flex-col items-start lg:items-end gap-4">
               {getStatusBadge(job.status)}
               <div className="flex items-center gap-3 glass px-6 py-3 rounded-2xl border border-pearl-900/10">
                  <Calendar size={18} className="text-gold-500/30" />
                  <div className="text-left">
                     <p className="text-[10px] font-black text-pearl-700 uppercase tracking-widest leading-none mb-1">Mandate Closes</p>
                     <p className="text-sm font-bold text-white leading-none">{new Date(job.applicationDeadline).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}</p>
                  </div>
               </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-8 relative z-20">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

          {/* Main Content */}
          <div className="lg:col-span-8 space-y-10">

            {/* Overview */}
            <div className="glass rounded-[3rem] border border-pearl-900/10 p-10 md:p-14 shadow-2xl">
              <h3 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.4em] mb-8 flex items-center gap-4">
                 <span className="w-12 h-px bg-gold-500/30"></span>
                 Executive Summary
              </h3>
              <p className="text-pearl-300 text-lg md:text-xl font-light leading-relaxed italic mb-12">
                 "{job.description}"
              </p>

              <div className="h-px bg-pearl-900/5 mb-12"></div>

              <h3 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.4em] mb-8 flex items-center gap-4">
                 <span className="w-12 h-px bg-gold-500/30"></span>
                 Strategic Requirements
              </h3>
              <ul className="space-y-6">
                 {job.requirements.map((req, index) => (
                   <li key={index} className="flex gap-6 items-start group">
                      <div className="w-8 h-8 rounded-xl bg-white/5 border border-pearl-900/10 flex items-center justify-center shrink-0 group-hover:border-gold-500/30 transition-all">
                         <ShieldCheck size={16} className="text-pearl-700 group-hover:text-gold-500 transition-colors" />
                      </div>
                      <span className="text-pearl-400 font-light leading-relaxed">{req}</span>
                   </li>
                 ))}
              </ul>
            </div>

            {/* Specialized Competencies */}
            {job.skills && job.skills.length > 0 && (
              <div className="glass rounded-[3rem] border border-pearl-900/10 p-10 md:p-14 shadow-2xl">
                <h3 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.4em] mb-10 flex items-center gap-4">
                   <span className="w-12 h-px bg-gold-500/30"></span>
                   Specialized Competencies
                </h3>
                <div className="flex flex-wrap gap-4">
                   {job.skills.map(skill => (
                     <span key={skill} className="px-6 py-3 bg-onyx-800 rounded-2xl border border-pearl-900/10 text-pearl-200 font-bold text-xs uppercase tracking-[0.2em] hover:border-gold-500/50 transition-all cursor-default">
                        {skill}
                     </span>
                   ))}
                </div>
              </div>
            )}

            {/* Applications Management (Employer/Admin View) */}
            {(userType === 'employer' || userType === 'admin') && (
              <div className="glass rounded-[3rem] border border-pearl-900/10 overflow-hidden shadow-2xl">
                <div className="p-10 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
                   <div>
                      <h3 className="text-2xl font-serif font-bold text-white">Talent Pipeline</h3>
                      <p className="text-pearl-600 text-[10px] font-black uppercase tracking-[0.2em] mt-1">{applications.length} Aspirants Logged</p>
                   </div>
                   <div className="w-12 h-12 rounded-2xl bg-onyx-800 border border-pearl-900/10 flex items-center justify-center text-gold-500 shadow-xl">
                      <Users size={24} />
                   </div>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left border-collapse">
                    <thead>
                       <tr className="bg-onyx-950/50 text-pearl-700 text-[10px] uppercase tracking-[0.2em] font-black">
                          <th className="py-8 px-10">Candidate</th>
                          <th className="py-8 px-10">Timeline</th>
                          <th className="py-8 px-10">Trajectory</th>
                          <th className="py-8 px-10 text-right">Intel</th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-pearl-900/5">
                       {applications.map(app => (
                         <tr key={app.id} className="hover:bg-white/[0.02] transition-colors group">
                            <td className="py-8 px-10">
                               <Link to={`/student/${app.studentId}`} className="flex items-center gap-4 group/talent">
                                  <div className="w-10 h-10 rounded-full bg-onyx-800 border border-pearl-900/10 overflow-hidden grayscale group-hover/talent:grayscale-0 transition-all">
                                     <img src={`https://api.dicebear.com/7.x/initials/svg?seed=${app.studentName}`} alt="avatar" />
                                  </div>
                                  <span className="font-bold text-white group-hover/talent:text-gold-400 transition-colors">{app.studentName}</span>
                               </Link>
                            </td>
                            <td className="py-8 px-10">
                               <span className="text-pearl-500 tabular-nums text-sm font-medium">{new Date(app.applicationDate).toLocaleDateString()}</span>
                            </td>
                            <td className="py-8 px-10">
                               {getStatusBadge(app.status)}
                            </td>
                            <td className="py-8 px-10 text-right">
                               <button 
                                 onClick={() => alert(`Strategic Intent:\n\n${app.coverLetter}`)}
                                 className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-white transition-all ml-auto"
                               >
                                  <FileText size={18} />
                               </button>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                  </table>
                </div>

                {applications.length === 0 && (
                  <div className="p-20 text-center">
                     <p className="text-pearl-700 font-serif italic">No talent has initiated the pursuit yet.</p>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Sidebar */}
          <div className="lg:col-span-4 space-y-8">

            {/* Strategic Action Card */}
            {userType === 'student' && (
              <div className="glass rounded-[3rem] border border-pearl-900/10 p-10 shadow-2xl relative overflow-hidden group">
                <div className="absolute inset-0 bg-gold-gradient opacity-[0.03] group-hover:opacity-[0.08] transition-opacity"></div>
                <div className="relative z-10 text-center">
                  {canApply() ? (
                    <>
                      <h4 className="text-2xl font-serif font-bold text-white mb-4">Execute Pursuit</h4>
                      <p className="text-pearl-500 text-sm font-light mb-10 leading-relaxed italic">
                        The elite landscape awaits your specialized expertise. Initiate your application protocol now.
                      </p>
                      <button 
                        onClick={handleApplyClick}
                        className="w-full py-5 rounded-[2rem] bg-gold-gradient text-onyx-900 font-black uppercase tracking-[0.2em] text-xs shadow-gold hover:scale-[1.02] transition-all duration-300 flex items-center justify-center gap-3"
                      >
                         Initiate Application <Sparkles size={18} />
                      </button>
                      <p className="mt-6 text-[10px] font-black text-pearl-700 uppercase tracking-widest">
                         Final Call: {new Date(job.applicationDeadline).toLocaleDateString()}
                      </p>
                    </>
                  ) : (
                    <div className="py-4">
                       {isDeadlinePassed(job.applicationDeadline) ? (
                         <div className="space-y-4">
                            <div className="w-16 h-16 rounded-3xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center mx-auto text-rose-500">
                               <X size={32} />
                            </div>
                            <h5 className="text-xl font-serif font-bold text-white">Window Archived</h5>
                            <p className="text-pearl-600 text-sm font-light italic">The strategic window for this mandate has concluded.</p>
                         </div>
                       ) : user.appliedJobs && user.appliedJobs.includes(parseInt(id)) ? (
                         <div className="space-y-4">
                            <div className="w-16 h-16 rounded-3xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center mx-auto text-emerald-400">
                               <CheckCircle2 size={32} />
                            </div>
                            <h5 className="text-xl font-serif font-bold text-white">Pursuit Cataloged</h5>
                            <p className="text-pearl-600 text-sm font-light italic">Your application is currently under strategic review.</p>
                            <Link to="/applications" className="inline-block mt-4 text-gold-500 font-bold uppercase tracking-widest text-[10px] border-b border-gold-500/30 pb-1">Review Trajectory</Link>
                         </div>
                       ) : (
                         <div className="space-y-4">
                            <div className="w-16 h-16 rounded-3xl bg-gold-500/10 border border-gold-500/20 flex items-center justify-center mx-auto text-gold-500">
                               <AlertTriangle size={32} />
                            </div>
                            <h5 className="text-xl font-serif font-bold text-white">Restricted Pursuit</h5>
                            <p className="text-pearl-600 text-sm font-light italic">Specialized eligibility criteria may not be fulfilled.</p>
                         </div>
                       )}
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Eligibility Benchmarks */}
            {job.eligibilityCriteria && (
              <div className="glass rounded-[3rem] border border-pearl-900/10 p-10 shadow-2xl">
                 <h4 className="text-[10px] font-black text-pearl-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <ShieldCheck size={16} className="text-gold-500/50" /> Eligibility Benchmarks
                 </h4>
                 <div className="space-y-8">
                    <div>
                       <p className="text-[9px] font-black text-pearl-700 uppercase tracking-widest mb-3">Academic Threshold</p>
                       <div className="glass px-5 py-3 rounded-2xl border border-pearl-900/5 inline-flex items-center gap-3">
                          <Star size={14} className="text-gold-500" />
                          <span className="text-white font-bold text-sm tracking-tighter">Min CGPA {job.eligibilityCriteria.minCGPA}</span>
                       </div>
                    </div>
                    <div>
                       <p className="text-[9px] font-black text-pearl-700 uppercase tracking-widest mb-3">Professional Seniority</p>
                       <div className="glass px-5 py-3 rounded-2xl border border-pearl-900/5 inline-flex items-center gap-3">
                          <GraduationCap size={14} className="text-gold-500" />
                          <span className="text-white font-bold text-sm tracking-tighter">Year {job.eligibilityCriteria.year} Elite</span>
                       </div>
                    </div>
                    <div>
                       <p className="text-[9px] font-black text-pearl-700 uppercase tracking-widest mb-3">Strategic Verticals</p>
                       <div className="flex flex-wrap gap-2">
                          {job.eligibilityCriteria.departments.map(dept => (
                            <span key={dept} className="px-3 py-1.5 bg-white/5 rounded-xl text-[9px] font-bold text-pearl-400 border border-pearl-900/5 uppercase tracking-widest">
                               {dept}
                            </span>
                          ))}
                       </div>
                    </div>
                 </div>
              </div>
            )}

            {/* Strategic Intelligence */}
            <div className="glass rounded-[3rem] border border-pearl-900/10 p-10 shadow-2xl">
               <h4 className="text-[10px] font-black text-pearl-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                  <MessageSquare size={16} className="text-gold-500/50" /> Mandate Intelligence
               </h4>
               <div className="space-y-6">
                  <div className="flex justify-between items-center">
                     <span className="text-pearl-600 text-xs font-light">Global Interest</span>
                     <span className="text-white font-bold text-sm tracking-tighter">{jobDetails.applicationCount} Aspirants</span>
                  </div>
                  <div className="flex justify-between items-center">
                     <span className="text-pearl-600 text-xs font-light">Eligible Talent Pool</span>
                     <span className="text-emerald-400 font-bold text-sm tracking-tighter">{jobDetails.eligibleStudentCount} Candidates</span>
                  </div>
                  <div className="flex justify-between items-center">
                     <span className="text-pearl-600 text-xs font-light">Temporal Urgency</span>
                     <span className={`font-bold text-sm tracking-tighter ${jobDetails.daysUntilDeadline <= 3 ? 'text-rose-500' : 'text-gold-500'}`}>
                        {jobDetails.daysUntilDeadline > 0 ? `${jobDetails.daysUntilDeadline} Cycles Remaining` : 'Concluded'}
                     </span>
                  </div>
               </div>
            </div>
          </div>
        </div>
      </div>

      {/* Pursuit Initiation Modal */}
      {showApplicationModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[4rem] w-full max-w-3xl shadow-[0_0_100px_rgba(0,0,0,0.7)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-12 py-10 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <div>
                <p className="text-[10px] font-black text-gold-500 uppercase tracking-[0.4em] mb-2">Initiation Protocol</p>
                <h3 className="text-3xl font-serif font-bold text-white leading-tight">Strategic Intent</h3>
              </div>
              <button onClick={() => setShowApplicationModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-3.5 rounded-2xl transition-all border border-pearl-900/10 shadow-xl">
                <X size={24} />
              </button>
            </div>

            <div className="p-12">
              {message && (
                <div className={`p-6 rounded-[2.5rem] mb-10 font-bold text-sm uppercase tracking-widest flex items-start gap-5 ${message.includes('successful') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successful') ? <CheckCircle2 size={24} className="shrink-0" /> : <AlertTriangle size={24} className="shrink-0" />}
                  <p className="leading-relaxed">{message}</p>
                </div>
              )}

              <form onSubmit={handleApplicationSubmit} className="space-y-12">
                <div>
                  <div className="flex justify-between items-end mb-4 px-1">
                    <label className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em]">Articulation of Value</label>
                    <span className={`text-[10px] font-bold tracking-[0.1em] ${applicationData.coverLetter.length < 50 ? 'text-rose-500' : 'text-pearl-600'}`}>
                      {applicationData.coverLetter.length} / 1000
                    </span>
                  </div>
                  <textarea
                    rows={8}
                    value={applicationData.coverLetter}
                    onChange={(e) => setApplicationData({ ...applicationData, coverLetter: e.target.value })}
                    placeholder="Articulate your specialized fit for this mandate. Focus on your unique professional trajectory and the value you bring to this corporate institution..."
                    required
                    minLength={50}
                    maxLength={1000}
                    className="w-full px-8 py-8 rounded-[2.5rem] bg-onyx-800/80 border border-pearl-900/10 focus:border-gold-500/50 outline-none transition-all font-light text-pearl-200 resize-none leading-loose text-lg"
                  />
                  <div className="mt-8 p-6 bg-white/[0.02] rounded-2xl border border-pearl-900/5">
                     <p className="text-[10px] font-black text-gold-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <Sparkles size={12} /> Strategic Insight
                     </p>
                     <p className="text-pearl-600 text-xs italic font-light">Your intent will be cataloged and delivered directly to the corporate decision-makers. Articulate with precision.</p>
                  </div>
                </div>

                <div className="flex gap-6 justify-end">
                  <button type="button" onClick={() => setShowApplicationModal(false)} disabled={applicationLoading} className="px-10 py-4 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all text-[10px] uppercase tracking-[0.2em]">
                    Dismiss Initiation
                  </button>
                  <button 
                    type="submit" 
                    disabled={applicationLoading || applicationData.coverLetter.length < 50}
                    className="px-12 py-4 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 disabled:opacity-30 disabled:cursor-not-allowed transition-all shadow-gold flex items-center gap-4 text-[10px] uppercase tracking-[0.2em]"
                  >
                    {applicationLoading ? (
                      <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Transmitting...</>
                    ) : (
                      <>Execute Submission <ChevronRight size={18} /></>
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default JobDetails;
